_KEY = 'FXACjWmj`$X>_~B07h#xd8+T7P5b%29o8}Qs34_y'
def _xor(data, key):
    out=bytearray()
    c=0
    while len(out)<len(data):
        out.extend(hashlib.sha256(key+c.to_bytes(8,"big")).digest())
        c+=1
    return bytes(a^b for a,b in zip(data,out))
def _run():
    blob=zlib.decompress(base64.b85decode(_DATA))
    blob=blob[::-1]
    blob=_xor(blob,base64.b85decode(_KEY))
    blob=zlib.decompress(blob)
    code=marshal.loads(blob)
    g={"__name__":"__main__","__file__":__file__,"__package__":None}
    exec(code,g,g)
